using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train model at startup and register pooled prediction engine
var serviceProvider = builder.Services.BuildServiceProvider();
var logger = serviceProvider.GetRequiredService<ILoggerFactory>().CreateLogger<TicketClassifierService>();
var trainerService = new TicketClassifierService(logger);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");

// Copy data file to output if running from project directory
var sourceDataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "tickets.csv");
if (File.Exists(sourceDataPath) && !File.Exists(dataPath))
{
    Directory.CreateDirectory(Path.GetDirectoryName(dataPath)!);
    File.Copy(sourceDataPath, dataPath);
}
if (!File.Exists(dataPath))
    dataPath = sourceDataPath;

var (_, modelPath) = trainerService.TrainAndEvaluate(dataPath);

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

